// SPDX-License-Identifier: Apache-2.0
package com.synexia.rewrite;

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HexFormat;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;

/**
 * Deterministic bounded schedule planner for recipe-mastery campaigns.
 *
 * <p>Small recipe families are proved exhaustively over every non-empty subset and every
 * permutation. When the factorial space exceeds the declared schedule budget, the planner fails
 * over to complete ordered-pair coverage: every recipe is exercised alone and every ordered
 * interaction A->B is exercised explicitly. Optional full-length schedules are then added while
 * budget remains. No random sampling is used.</p>
 */
public final class M3RecipeMasterySchedulePlanner {
    public static final int MAX_RECIPES = 16;
    public static final int MAX_SCHEDULES = 10_000;

    public enum Coverage {
        EXHAUSTIVE,
        ORDERED_PAIRWISE
    }

    public record Schedule(String subset, List<String> order) {
        public Schedule {
            subset = required(subset, "subset");
            order = List.copyOf(Objects.requireNonNull(order, "order"));
            if (order.isEmpty() || order.size() > MAX_RECIPES) {
                throw new IllegalArgumentException("schedule recipe count");
            }
            LinkedHashSet<String> seen = new LinkedHashSet<>();
            for (String value : order) {
                String id = checkedRecipeId(value);
                if (!seen.add(id)) {
                    throw new IllegalArgumentException("duplicate recipe in schedule: " + id);
                }
            }
            String expectedSubset = subsetId(order);
            if (!subset.equals(expectedSubset)) {
                throw new IllegalArgumentException(
                        "subset/order mismatch: subset="
                                + subset
                                + " expected="
                                + expectedSubset);
            }
        }
    }

    public record Plan(Coverage coverage, List<Schedule> schedules, String rootSha256) {
        public Plan {
            coverage = Objects.requireNonNull(coverage, "coverage");
            schedules = List.copyOf(Objects.requireNonNull(schedules, "schedules"));
            if (schedules.isEmpty() || schedules.size() > MAX_SCHEDULES) {
                throw new IllegalArgumentException("schedule plan size");
            }

            LinkedHashSet<String> uniqueOrders = new LinkedHashSet<>();
            LinkedHashSet<String> universe = new LinkedHashSet<>();
            for (Schedule schedule : schedules) {
                String key = orderKey(schedule.order());
                if (!uniqueOrders.add(key)) {
                    throw new IllegalArgumentException("duplicate schedule order: " + key);
                }
                universe.addAll(schedule.order());
            }
            if (universe.isEmpty() || universe.size() > MAX_RECIPES) {
                throw new IllegalArgumentException("recipe universe size");
            }
            List<String> ids = plannerIds(schedules, universe);
            verifyCoverage(coverage, schedules, ids);

            rootSha256 = requireSha256(rootSha256, "rootSha256");
            String expectedRoot = root(coverage, schedules);
            if (!rootSha256.equals(expectedRoot)) {
                throw new IllegalArgumentException("schedule plan root mismatch");
            }
        }

        /** Planning evidence is never source-mutation authority. */
        public boolean mutationAuthority() {
            return false;
        }

        /** Planning evidence is never canonical promotion authority. */
        public boolean promotionAuthority() {
            return false;
        }
    }

    private M3RecipeMasterySchedulePlanner() {}

    public static Plan plan(List<String> recipeIds, int maxSchedules) {
        List<String> ids = checkedIds(recipeIds);
        if (maxSchedules < 1 || maxSchedules > MAX_SCHEDULES) {
            throw new IllegalArgumentException("maxSchedules");
        }

        long exact = exhaustiveCount(ids.size(), maxSchedules);
        List<Schedule> schedules;
        Coverage coverage;
        if (exact <= maxSchedules) {
            schedules = exhaustive(ids, maxSchedules);
            coverage = Coverage.EXHAUSTIVE;
        } else {
            schedules = orderedPairwise(ids, maxSchedules);
            coverage = Coverage.ORDERED_PAIRWISE;
        }
        return new Plan(coverage, schedules, root(coverage, schedules));
    }

    private static List<String> checkedIds(List<String> recipeIds) {
        Objects.requireNonNull(recipeIds, "recipeIds");
        if (recipeIds.isEmpty() || recipeIds.size() > MAX_RECIPES) {
            throw new IllegalArgumentException("recipe count");
        }
        ArrayList<String> ids = new ArrayList<>(recipeIds.size());
        Set<String> seen = new LinkedHashSet<>();
        for (String value : recipeIds) {
            String id = checkedRecipeId(value);
            if (!seen.add(id)) throw new IllegalArgumentException("duplicate recipe id: " + id);
            ids.add(id);
        }
        return List.copyOf(ids);
    }

    private static long exhaustiveCount(int n, int ceiling) {
        long total = 0L;
        long permutations = 1L;
        for (int k = 1; k <= n; k++) {
            permutations = Math.multiplyExact(permutations, n - k + 1L);
            if (permutations > ceiling || total > ceiling - permutations) {
                return (long) ceiling + 1L;
            }
            total += permutations;
        }
        return total;
    }

    private static List<Schedule> exhaustive(List<String> ids, int maxSchedules) {
        ArrayList<Schedule> result = new ArrayList<>();
        int combinations = 1 << ids.size();
        for (int mask = 1; mask < combinations; mask++) {
            ArrayList<String> selected = new ArrayList<>();
            for (int index = 0; index < ids.size(); index++) {
                if ((mask & (1 << index)) != 0) selected.add(ids.get(index));
            }
            ArrayList<List<String>> permutations = new ArrayList<>();
            permute(selected, 0, permutations, maxSchedules - result.size());
            String subset = subsetId(selected);
            for (List<String> permutation : permutations) {
                if (result.size() >= maxSchedules) {
                    throw new IllegalArgumentException("recipe schedule budget exceeded");
                }
                result.add(new Schedule(subset, permutation));
            }
        }
        return List.copyOf(result);
    }

    private static List<Schedule> orderedPairwise(List<String> ids, int maxSchedules) {
        long required = Math.multiplyExact((long) ids.size(), ids.size());
        if (required > maxSchedules) {
            throw new IllegalArgumentException(
                    "schedule budget too small for complete ordered-pair coverage: need "
                            + required
                            + " schedules");
        }

        ArrayList<Schedule> result = new ArrayList<>();
        LinkedHashSet<String> unique = new LinkedHashSet<>();
        for (String id : ids) add(result, unique, new Schedule(id, List.of(id)), maxSchedules);
        for (int left = 0; left < ids.size(); left++) {
            for (int right = 0; right < ids.size(); right++) {
                if (left == right) continue;
                List<String> pair = List.of(ids.get(left), ids.get(right));
                add(result, unique, new Schedule(subsetId(pair), pair), maxSchedules);
            }
        }

        if (ids.size() > 2) {
            add(result, unique, new Schedule(subsetId(ids), ids), maxSchedules);
            ArrayList<String> reverse = new ArrayList<>(ids);
            Collections.reverse(reverse);
            add(result, unique, new Schedule(subsetId(ids), reverse), maxSchedules);

            for (int shift = 1; shift < ids.size() && result.size() < maxSchedules; shift++) {
                ArrayList<String> rotated = new ArrayList<>(ids.size());
                for (int index = 0; index < ids.size(); index++) {
                    rotated.add(ids.get((index + shift) % ids.size()));
                }
                add(result, unique, new Schedule(subsetId(ids), rotated), maxSchedules);
            }
        }
        return List.copyOf(result);
    }

    private static void add(
            List<Schedule> output,
            Set<String> unique,
            Schedule schedule,
            int maxSchedules) {
        if (output.size() >= maxSchedules) return;
        String key = String.join("\u0000", schedule.order());
        if (unique.add(key)) output.add(schedule);
    }

    private static void permute(
            List<String> values,
            int offset,
            List<List<String>> output,
            int budget) {
        if (offset == values.size()) {
            if (output.size() >= budget) {
                throw new IllegalArgumentException("recipe schedule budget exceeded");
            }
            output.add(List.copyOf(values));
            return;
        }
        for (int index = offset; index < values.size(); index++) {
            Collections.swap(values, offset, index);
            permute(values, offset + 1, output, budget);
            Collections.swap(values, offset, index);
        }
    }

    private static List<String> plannerIds(
            List<Schedule> schedules,
            Set<String> universe) {
        List<String> singletons =
                schedules.stream()
                        .filter(schedule -> schedule.order().size() == 1)
                        .map(schedule -> schedule.order().getFirst())
                        .toList();
        if (singletons.size() != universe.size()
                || !new LinkedHashSet<>(singletons).equals(universe)) {
            throw new IllegalArgumentException("singleton recipe universe drift");
        }
        return singletons;
    }

    private static void verifyCoverage(
            Coverage coverage,
            List<Schedule> schedules,
            List<String> ids) {
        List<Schedule> expected =
                switch (coverage) {
                    case EXHAUSTIVE -> {
                        long exact = exhaustiveCount(ids.size(), MAX_SCHEDULES);
                        if (exact > MAX_SCHEDULES || schedules.size() != exact) {
                            throw new IllegalArgumentException(
                                    "incomplete exhaustive schedule coverage");
                        }
                        yield exhaustive(ids, MAX_SCHEDULES);
                    }
                    case ORDERED_PAIRWISE -> {
                        if (ids.size() < 3) {
                            throw new IllegalArgumentException(
                                    "ordered-pairwise coverage requires at least 3 recipes");
                        }
                        long mandatory = Math.multiplyExact((long) ids.size(), ids.size());
                        long maximum = Math.addExact(mandatory, ids.size() + 1L);
                        if (schedules.size() < mandatory || schedules.size() > maximum) {
                            throw new IllegalArgumentException(
                                    "ordered-pairwise schedule count");
                        }
                        yield orderedPairwise(ids, schedules.size());
                    }
                };
        if (!schedules.equals(expected)) {
            throw new IllegalArgumentException(
                    "non-canonical " + coverage.name().toLowerCase(java.util.Locale.ROOT)
                            + " schedule order");
        }
    }

    private static String orderKey(List<String> order) {
        return String.join("\u0000", order);
    }

    private static String checkedRecipeId(String value) {
        String id = required(value, "recipeId");
        if (!id.matches("[A-Za-z0-9][A-Za-z0-9_.-]{0,95}")) {
            throw new IllegalArgumentException("invalid recipe id: " + id);
        }
        return id;
    }

    private static String subsetId(List<String> ids) {
        return ids.stream().sorted().reduce((left, right) -> left + "+" + right).orElseThrow();
    }

    private static String root(Coverage coverage, List<Schedule> schedules) {
        MessageDigest digest = digest();
        frame(digest, "M3_RECIPE_MASTERY_SCHEDULES_V1");
        frame(digest, coverage.name());
        frame(digest, Integer.toString(schedules.size()));
        for (Schedule schedule : schedules) {
            frame(digest, schedule.subset());
            frame(digest, Integer.toString(schedule.order().size()));
            for (String id : schedule.order()) frame(digest, id);
        }
        return HexFormat.of().formatHex(digest.digest());
    }

    private static MessageDigest digest() {
        try {
            return MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException impossible) {
            throw new ExceptionInInitializerError(impossible);
        }
    }

    private static void frame(MessageDigest digest, String value) {
        byte[] bytes = value.getBytes(java.nio.charset.StandardCharsets.UTF_8);
        digest.update((byte) (bytes.length >>> 24));
        digest.update((byte) (bytes.length >>> 16));
        digest.update((byte) (bytes.length >>> 8));
        digest.update((byte) bytes.length);
        digest.update(bytes);
    }

    private static String required(String value, String field) {
        String checked = Objects.requireNonNull(value, field).strip();
        if (checked.isEmpty()) throw new IllegalArgumentException(field);
        return checked;
    }

    private static String requireSha256(String value, String field) {
        String checked = Objects.requireNonNull(value, field);
        if (!checked.matches("[0-9a-f]{64}")) throw new IllegalArgumentException(field);
        return checked;
    }
}
